function validate([nums]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 100000 values.';
  const count = new Array(n + 1).fill(0);
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Each value is between 1 and nums.length.';
    if (++count[v] > 2) return 'No value may appear more than twice.';
  }
  return null;
}

