function findDuplicates(nums) {
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    const value = Math.abs(nums[i]);
    const index = value - 1;
    if (nums[index] < 0) {
      result.push(value);
    } else {
      nums[index] = -nums[index];
    }
  }
  return result;
}

