function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  // pairs values appear twice and n - 2 * pairs appear once, so the length is exactly n.
  const pairs = Math.floor(rand() * (Math.floor(n / 2) + 1));
  const values = shuffle(Array.from({ length: n }, (_, i) => i + 1)).slice(0, n - pairs);
  return [shuffle([...values, ...values.slice(0, pairs)])];
}
